# T-3100 (ADR-064). The CRM log and the WhatsApp log as one read view. A WhatsApp row
# mirrored into a CRM row of the same organization shows once (as the CRM row); a CRM
# row mirrored from another organization's WhatsApp chat (KI-073) is left out.
VIEW = """
CREATE VIEW unified_messages AS
SELECT 'crm:' || cm.id::text AS id, 'crm'::varchar AS source, cm.id AS row_id,
       cm.lead_id, NULL::uuid AS session_id, cm.enquiry_id,
       CASE WHEN cm.enquiry_id IS NULL THEN l.organization_id ELSE e.organization_id END AS organization_id,
       cm.sender_id, cm.direction, cm.channel::varchar AS channel, 'text'::varchar AS msg_type, cm.body,
       cm.wa_message_id::varchar AS wa_message_id,
       EXISTS (SELECT 1 FROM message_attachments a WHERE a.message_id = cm.id) AS has_media,
       cm.created_at
  FROM conversation_messages cm
  JOIN leads l ON l.id = cm.lead_id
  LEFT JOIN enquiries e ON e.id = cm.enquiry_id
 WHERE NOT (cm.channel = 'whatsapp' AND cm.wa_message_id <> '' AND EXISTS (
         SELECT 1 FROM whatsapp_messages w JOIN whatsapp_sessions s ON s.id = w.session_id
          WHERE w.wa_message_id = cm.wa_message_id
            AND s.organization_id IS DISTINCT FROM l.organization_id))
UNION ALL
SELECT 'wa:' || w.id::text, 'whatsapp'::varchar, w.id,
       NULL::uuid, w.session_id, NULL::uuid, s.organization_id,
       NULL::uuid, w.direction, 'whatsapp'::varchar, w.msg_type::varchar, w.body,
       w.wa_message_id::varchar,
       (w.media_id <> '' OR w.media_url <> ''), w.created_at
  FROM whatsapp_messages w
  JOIN whatsapp_sessions s ON s.id = w.session_id
 WHERE NOT EXISTS (
         SELECT 1 FROM conversation_messages c JOIN leads l2 ON l2.id = c.lead_id
          WHERE w.wa_message_id <> '' AND c.wa_message_id = w.wa_message_id AND c.channel = 'whatsapp'
            AND l2.organization_id IS NOT DISTINCT FROM s.organization_id)
"""


def link_contacts(apps, schema_editor):
    """Phone-only contacts from before: link the registered person; the phone stays until the contract."""
    CRMContact = apps.get_model('leads', 'CRMContact')
    User = apps.get_model('users', 'User')
    for c in CRMContact.objects.filter(user__isnull=True).exclude(phone='').iterator():
        digits = c.phone.lstrip('+')
        user = User.objects.filter(phone__in=[digits, '+' + digits]).first()
        if user and not CRMContact.objects.filter(organization_id=c.organization_id, user=user).exists():
            CRMContact.objects.filter(pk=c.pk).update(user=user)


